import{z as n,x as i,o as A,c as o,q as e,j as t,D as a,d as B,s as r,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"合成数据的谱系与分类","description":"","frontmatter":{"title":"合成数据的谱系与分类","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/synthetic-taxonomy.md","filePath":"llm/synthetic-taxonomy.md","lastUpdated":1791063341000}'),m={name:"llm/synthetic-taxonomy.md"};function D(p,E,C,d,F,h){const l=i("Mermaid");return A(),o("div",null,[E[2]||(E[2]=e('<h1 id="合成数据的谱系与分类" tabindex="-1">合成数据的谱系与分类 <a class="header-anchor" href="#合成数据的谱系与分类" aria-label="Permalink to &quot;合成数据的谱系与分类&quot;">​</a></h1><div class="epigraph"><p>合成数据的分类学不是文献综述，是风险清单：每一种生成方式都对应一种特定的失败模式，和一只专门管它的阀门。</p><footer>—— 据 Wang 等 Self-Instruct；Gunasekar 等 Textbooks Are All You Need 整理</footer></div><p><a href="/llm/rm-engineering-map">上一课</a>把奖励模型工程收成一条主线：RM 是比较数据的回归器，数据定天花板，策略做放大器；根本解只有改数据的经验分布这一个入口。天花板要抬，除了向标注员买，还可以让模型自己造数据——合成数据。此前<a href="/llm/self-instruct">自指令</a>、<a href="/llm/textbook-synthetic">教科书式合成</a>、<a href="/llm/synthetic-pretrain">合成数据在预训练中的位置</a>、<a href="/llm/reasoning-distill-small">推理蒸馏到小模型</a>、<a href="/llm/model-collapse-empirics">模型坍缩的实证</a>散落在各课序里，各讲各的管线与失败。本课程把散点收拢成一门工程学科：合成数据不是一种数据，而是一组生产线，用同一套语言描述、验收、止损。本课先建坐标系。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>工程决策里第一个问题从来不是「怎么生成」，而是「选哪条生成线」。给指令池扩覆盖、给推理模型造题、给预训练补稀疏域，三条线的原料、验证器、风险完全不同。把「合成数据」当一个桶，会犯两类错：用预训练网页的启发式过滤去质检数学题——质量信号根本不在文本表面上；或者用自指令的去重阈值去管纯生成数据——重复风险与坍缩风险不是一回事。分类的目的，是让每类数据在进配比之前就带着自己的风险说明书。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把任何一条合成生产线写成五元组：原料、生成器、验证器、过滤器、配比。原料是种子与锚点：种子喂给生成器，锚点对真实分布校准。生成器按来源分三档：无源生成（教师自由采样）、有源改写（围绕种子自举、演化、改写、回译）、程序生成（模板加符号）。验证器按真值来源分三档：程序可验证（答案核对、单元测试、执行反馈）、裁判打分（教师或裁判模型）、无验证（纯生成直接入库）。过滤器与配比留给后续各课。<span class="marginnote">五元组就是给每条合成生产线办一张身份证：原料=用什么做种子，生成器=谁来写，验证器=谁判对错，过滤器=谁拦坏样本，配比=进配方占几成。讨论任何合成数据之前，先把这五项填出来。</span></p><p>三档来源对应三类风险。无源生成怕分布坍缩：没有锚点，模型自食输出，尾部先丢、熵收缩。有源改写怕种子覆盖：生成的多样性上限被种子池锁死，种子偏了整条线跟着偏。程序生成怕模板化：真值干净但表面分布窄，模型学到的是模板正则性而不是能力。验证器的可信度决定上游可以多激进：有程序真值的域可以放开采样量，靠裁判打分的域要把裁判偏置当一等公民来管。</p>',8)),(A(),t(s,null,{default:a(()=>[r(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8E%9F%E6%96%99%EF%BC%9A%E7%A7%8D%E5%AD%90%E4%B8%8E%E7%9C%9F%E5%AE%9E%E9%94%9A%E7%82%B9%22%5D%20--%3E%20GEN%7B%22%E7%94%9F%E6%88%90%E5%99%A8%E6%9D%A5%E6%BA%90%22%7D%0A%20%20GEN%20--%3E%7C%22%E6%97%A0%E6%BA%90%E7%94%9F%E6%88%90%22%7C%20R1%5B%22%E9%A3%8E%E9%99%A9%EF%BC%9A%E5%88%86%E5%B8%83%E5%9D%8D%E7%BC%A9%22%5D%0A%20%20GEN%20--%3E%7C%22%E6%9C%89%E6%BA%90%E6%94%B9%E5%86%99%22%7C%20R2%5B%22%E9%A3%8E%E9%99%A9%EF%BC%9A%E7%A7%8D%E5%AD%90%E8%A6%86%E7%9B%96%22%5D%0A%20%20GEN%20--%3E%7C%22%E7%A8%8B%E5%BA%8F%E7%94%9F%E6%88%90%22%7C%20R3%5B%22%E9%A3%8E%E9%99%A9%EF%BC%9A%E6%A8%A1%E6%9D%BF%E5%8C%96%22%5D%0A%20%20R1%20--%3E%20VER%7B%22%E9%AA%8C%E8%AF%81%E5%99%A8%E6%A1%A3%E4%BD%8D%22%7D%0A%20%20R2%20--%3E%20VER%0A%20%20R3%20--%3E%20VER%0A%20%20VER%20--%3E%7C%22%E7%A8%8B%E5%BA%8F%E7%9C%9F%E5%80%BC%22%7C%20OUT%5B%22%E6%BF%80%E8%BF%9B%E6%94%BE%E9%87%8F%22%5D%0A%20%20VER%20--%3E%7C%22%E8%A3%81%E5%88%A4%E6%89%93%E5%88%86%22%7C%20JUDGE%5B%22%E5%85%88%E7%AE%A1%E8%A3%81%E5%88%A4%E5%81%8F%E7%BD%AE%22%5D%0A%20%20VER%20--%3E%7C%22%E6%97%A0%E9%AA%8C%E8%AF%81%22%7C%20GATE%5B%22%E6%9C%80%E5%B0%8F%E5%8D%A0%E6%AF%94%E5%8A%A0%E4%BA%BA%E5%B7%A5%E6%8A%BD%E6%A3%80%22%5D%0A%20%20OUT%20--%3E%20MIX%5B%22%E8%BF%87%E6%BB%A4%E4%B8%8E%E9%85%8D%E6%AF%94%EF%BC%9A%E5%90%8E%E7%BB%AD%E5%90%84%E8%AF%BE%22%5D%0A%20%20JUDGE%20--%3E%20MIX%0A%20%20GATE%20--%3E%20MIX%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么分类决定风险而不只是决定出处：因为验证器是传导链的中枢。上游生成得再野，程序真值能在入库前拦下错误——数学与代码敢放量，靠的是验证器比生成器可信。反过来，裁判打分的数据里，裁判的偏置会原样写进训练分布：教师偏爱长答案，长答案被反复保留，长度偏置从裁判流入模型。所以合成数据能占多少配比，不取决于生成多便宜，取决于这条线上「错误被拦截的比例」。<span class="marginnote">验证器是中枢可以类比食品出厂检验：原料再野，出厂检验用仪器（程序真值），问题就地拦下；若检验靠品鉴师的口味（裁判打分），师傅偏甜，全厂产品就悄悄变甜——偏置从检验环节原样写进产品。</span><a href="/llm/model-collapse-empirics">模型坍缩的实证</a>给出的是下界情形：无验证、无回混的闭环，几代之内尾部就近乎不可逆地丢掉；而约一成的真实数据回混就能大幅推迟坍缩——锚点在谱系表里是最高优先级。<span class="marginnote">「约一成回混」给个直觉：相当于每生成十批数据掺进一批真实数据。它不是要把合成稀释掉，而是给分布拴一个真实锚点——没有这一成，闭环几代之内尾部先丢，而且几乎不可逆。</span></p>',2)),(A(),t(s,null,{default:a(()=>[r(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20CAND%5B%22%E5%80%99%E9%80%89%E6%B1%A0%EF%BC%9A%E5%AF%B9%E9%94%99%E4%B8%8E%E9%95%BF%E7%9F%AD%E6%B7%B7%E6%9D%82%22%5D%20--%3E%20V1%7B%22%E9%AA%8C%E8%AF%81%E5%99%A8%EF%BC%9A%E7%A8%8B%E5%BA%8F%E7%9C%9F%E5%80%BC%22%7D%0A%20%20V1%20--%3E%7C%E5%8F%AA%E8%AE%A4%E7%AD%94%E6%A1%88%E5%AF%B9%E9%94%99%7C%20P1%5B%22%E9%A3%8E%E6%A0%BC%E4%B8%8D%E4%BC%A0%E5%AF%BC%EF%BC%9A%E5%8F%AF%E6%BF%80%E8%BF%9B%E6%94%BE%E9%87%8F%22%5D%0A%20%20CAND%20--%3E%20V2%7B%22%E9%AA%8C%E8%AF%81%E5%99%A8%EF%BC%9A%E8%A3%81%E5%88%A4%E6%89%93%E5%88%86%22%7D%0A%20%20V2%20--%3E%7C%E5%81%8F%E7%88%B1%E9%95%BF%E7%AD%94%E6%A1%88%7C%20P2%5B%22%E4%BF%9D%E7%95%99%E9%9B%86%E9%87%8C%E9%95%BF%E7%AD%94%E6%A1%88%E8%B6%85%E9%A2%9D%22%5D%0A%20%20P2%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%E5%88%86%E5%B8%83%EF%BC%9A%E9%95%BF%E5%BA%A6%E5%81%8F%E7%BD%AE%E5%86%99%E5%85%A5%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20TRAIN%20--%3E%20NEXT%5B%22%E6%A8%A1%E5%9E%8B%E5%86%8D%E5%BD%93%E6%95%99%E5%B8%88%E6%88%96%E8%A3%81%E5%88%A4%EF%BC%9A%E5%81%8F%E7%BD%AE%E6%94%BE%E5%A4%A7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">这张图回答的问题是：偏置沿哪条路进入模型。同是验证器，程序真值只传「对错」这一个比特，风格就地截断；裁判打分连风格一起放行，且经「模型再当裁判」的回路逐轮放大——这就是验证器档位决定上游激进度的机制根源。</span></p><p><span class="marginnote">Alpaca 用 Self-Instruct 式自举生成 5.2 万条指令，公开口径 API 成本不到五百美元——生成成本从人月降到美元之后，工程重心整体从「采集」移到「控制」：原料、验证、过滤、配比取代了标注指南。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>谱系表本身不产生质量，它只保证你问对了问题。三轴之间有耦合：同一条线可以换验证器（数学题从裁判打分换成程序核对），风险结构随之改变，分类要跟着重画。教师模型的上限是所有线的共同天花板——谱系再精巧，也生成不出教师分布之外的能力。另外，本课程把人写数据当外部锚点而不是一类合成：人写与合成的分工在<a href="/llm/human-vs-synthetic-instruct">人写 vs 合成指令</a>已讲，此处只取结论——人写定义好回答，合成扩张覆盖。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>合成生产线是五元组：原料、生成器、验证器、过滤器、配比。</li><li>来源三档：无源生成怕坍缩，有源改写怕种子覆盖，程序生成怕模板化。</li><li>验证器三档：程序真值可放量，裁判打分先管偏置，无验证只配最小占比。</li><li>验证器可信度决定上游激进度，错误拦截比例决定合成占比上限。</li><li>真实数据回混与真实锚点是所有线的共同保险。</li><li>出处：Wang 等 Self-Instruct 2022；Gunasekar 等 2023；Shumailov 等 2024。</li></ul>',6))])}const f=n(m,[["render",D]]);export{_ as __pageData,f as default};
